<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #0b0c10;
    --panel: #1f2833;
    --accent: #66fcf1;
    --accent-dim: #45a29e;
    --text: #c5c6c7;
    --dead: #111;
    --alive: #66fcf1;
    --grid-line: #222;
  }

  * { box-sizing: border-box; }

  html, body {
    margin: 0;
    height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .container {
    text-align: center;
    padding: 1rem;
  }

  h1 {
    margin: 0 0 0.75rem;
    font-size: 1.6rem;
    letter-spacing: 1px;
    color: var(--accent);
    text-shadow: 0 0 10px rgba(102, 252, 241, 0.4);
  }

  #life {
    display: block;
    width: 600px;
    height: 600px;
    max-width: 92vw;
    max-height: 92vw;
    background: var(--dead);
    border: 2px solid var(--panel);
    border-radius: 8px;
    box-shadow: 0 0 25px rgba(102, 252, 241, 0.15);
    cursor: crosshair;
    margin: 0 auto 1rem;
  }

  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    justify-content: center;
  }

  button {
    background: var(--panel);
    color: var(--text);
    border: 2px solid var(--accent-dim);
    border-radius: 999px;
    padding: 0.55rem 1.2rem;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.1s ease, box-shadow 0.2s ease, background 0.2s ease;
  }

  button:hover {
    background: #2a3a47;
    box-shadow: 0 0 12px rgba(102, 252, 241, 0.25);
  }

  button:active {
    transform: scale(0.95);
  }

  button.active {
    background: var(--accent);
    color: var(--bg);
    border-color: var(--accent);
    box-shadow: 0 0 16px rgba(102, 252, 241, 0.5);
  }

  .hint {
    margin-top: 0.75rem;
    font-size: 0.8rem;
    opacity: 0.7;
  }
</style>
</head>
<body>
<div class="container">
  <h1>Conway's Game of Life</h1>
  <canvas id="life"></canvas>
  <div class="controls">
    <button id="step" type="button">Step</button>
    <button id="play" type="button">Play</button>
    <button id="random" type="button">Random</button>
    <button id="clear" type="button">Clear</button>
  </div>
  <div class="hint">Click or drag on the grid to paint cells alive or dead</div>
</div>

<script>
(function () {
  const W = 50; // cells across
  const H = 50; // cells down
  const CSS_SIZE = 600; // CSS pixels

  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');

  // Scale canvas for crisp rendering on high-DPI screens
  const dpr = window.devicePixelRatio || 1;
  canvas.width = CSS_SIZE * dpr;
  canvas.height = CSS_SIZE * dpr;
  canvas.style.width = CSS_SIZE + 'px';
  canvas.style.height = CSS_SIZE + 'px';
  ctx.scale(dpr, dpr);

  const cellW = CSS_SIZE / W;
  const cellH = CSS_SIZE / H;

  // The simulation grid
  const grid = new Uint8Array(W * H);

  function idx(x, y) {
    return y * W + x;
  }

  function inBounds(x, y) {
    return x >= 0 && x < W && y >= 0 && y < H;
  }

  function draw() {
    // Clear background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, CSS_SIZE, CSS_SIZE);

    // Draw grid lines
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x++) {
      ctx.moveTo(x * cellW, 0);
      ctx.lineTo(x * cellW, CSS_SIZE);
    }
    for (let y = 0; y <= H; y++) {
      ctx.moveTo(0, y * cellH);
      ctx.lineTo(CSS_SIZE, y * cellH);
    }
    ctx.stroke();

    // Draw live cells
    ctx.fillStyle = '#66fcf1';
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[idx(x, y)] === 1) {
          ctx.fillRect(x * cellW + 1, y * cellH + 1, cellW - 2, cellH - 2);
        }
      }
    }
  }

  function neighbours(x, y) {
    let count = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (inBounds(nx, ny) && grid[idx(nx, ny)] === 1) {
          count++;
        }
      }
    }
    return count;
  }

  function stepGeneration() {
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const n = neighbours(x, y);
        const alive = grid[idx(x, y)] === 1;
        if (alive) {
          next[idx(x, y)] = (n === 2 || n === 3) ? 1 : 0;
        } else {
          next[idx(x, y)] = (n === 3) ? 1 : 0;
        }
      }
    }
    grid.set(next);
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.3 ? 1 : 0;
    }
    draw();
  }

  function clearGrid() {
    grid.fill(0);
    draw();
  }

  // Public API
  window.life = {
    w: W,
    h: H,

    get(x, y) {
      if (!inBounds(x, y)) return 0;
      return grid[idx(x, y)];
    },

    set(x, y, v) {
      if (!inBounds(x, y)) return;
      grid[idx(x, y)] = v ? 1 : 0;
      draw();
    },

    step() {
      stepGeneration();
    },

    clear() {
      clearGrid();
    }
  };

  // Controls
  const btnStep = document.getElementById('step');
  const btnPlay = document.getElementById('play');
  const btnRandom = document.getElementById('random');
  const btnClear = document.getElementById('clear');

  let playing = false;
  let timer = null;

  function stop() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
    playing = false;
    btnPlay.textContent = 'Play';
    btnPlay.classList.remove('active');
  }

  function start() {
    if (timer) return;
    playing = true;
    btnPlay.textContent = 'Pause';
    btnPlay.classList.add('active');
    timer = setInterval(() => stepGeneration(), 120);
  }

  btnStep.addEventListener('click', () => {
    stop();
    stepGeneration();
  });

  btnPlay.addEventListener('click', () => {
    if (playing) stop(); else start();
  });

  btnRandom.addEventListener('click', () => {
    stop();
    randomize();
  });

  btnClear.addEventListener('click', () => {
    stop();
    clearGrid();
  });

  // Click / drag painting
  let paintingValue = null;

  function cellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor(((e.clientX - rect.left) / rect.width) * W);
    const y = Math.floor(((e.clientY - rect.top) / rect.height) * H);
    return { x, y };
  }

  canvas.addEventListener('mousedown', (e) => {
    e.preventDefault();
    const { x, y } = cellFromEvent(e);
    if (!inBounds(x, y)) return;
    paintingValue = grid[idx(x, y)] === 1 ? 0 : 1;
    window.life.set(x, y, paintingValue);
  });

  canvas.addEventListener('mousemove', (e) => {
    if (paintingValue === null) return;
    const { x, y } = cellFromEvent(e);
    if (!inBounds(x, y)) return;
    if (grid[idx(x, y)] !== paintingValue) {
      window.life.set(x, y, paintingValue);
    }
  });

  window.addEventListener('mouseup', () => {
    paintingValue = null;
  });

  canvas.addEventListener('mouseleave', () => {
    paintingValue = null;
  });

  // Touch support
  canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    const { x, y } = cellFromEvent(t);
    if (!inBounds(x, y)) return;
    paintingValue = grid[idx(x, y)] === 1 ? 0 : 1;
    window.life.set(x, y, paintingValue);
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    const { x, y } = cellFromEvent(t);
    if (!inBounds(x, y)) return;
    if (grid[idx(x, y)] !== paintingValue) {
      window.life.set(x, y, paintingValue);
    }
  }, { passive: false });

  window.addEventListener('touchend', () => {
    paintingValue = null;
  });

  // Seed a glider and a blinker so the grid is interesting on load
  function seedDemo() {
    clearGrid();
    // Blinker
    window.life.set(10, 10, 1);
    window.life.set(11, 10, 1);
    window.life.set(12, 10, 1);
    // Glider
    window.life.set(20, 5, 1);
    window.life.set(21, 6, 1);
    window.life.set(19, 7, 1);
    window.life.set(20, 7, 1);
    window.life.set(21, 7, 1);
  }

  seedDemo();
})();
</script>
</body>
</html>
